def compute(vars):
    canadian_nol = vars["v1"]
    state_nol = vars["v2"]

    if state_nol == 0:
        return None

    ratio = canadian_nol / state_nol
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "canadian_nol": canadian_nol,
            "state_nol": state_nol,
            "ratio": ratio,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
